const raw = String($json.body?.q || '');
const clean = raw.replace(/['"\\;]/g, '').trim().slice(0, 120);
return [{ json: { q: clean } }];

const items = $input.all();
const results = [];
for (const i of items) {
  const name = i.json['Наименование'];
  if (!name) continue;
  results.push({
    наименование: name,
    ед_измерения: i.json['Ед.измерения.'] || '',
    артикул: i.json['Артикул'] || '',
    цена_оптовая: i.json['Цена (оптовая)'] ?? null,
    валюта: i.json['Валюта'] || ''
  });
}
return [{ json: { results } }];
